#!/usr/bin/env python3
"""Classify libbench2 problem strings (as generated by FFTW's tests/check.pl)
into feature categories, mirroring libbench2/problem.c's grammar.
Usage: classify_problems.py problems.txt   (one problem per line, or 'verify <p>')"""
import re, sys, collections, json

def parse(s):
    p = dict(inplace=False, destroy=False, split=False, sign=-1, kind='c', transpose=False)
    i = 0
    while i < len(s) and s[i].lower() in 'iod/fb-+rckt[]':
        c = s[i].lower()
        if c == 'i': p['inplace'] = True
        elif c == 'o': p['inplace'] = False
        elif c == 'd': p['destroy'] = True
        elif c == '/': p['split'] = True
        elif c in 'f-': p['sign'] = -1
        elif c in 'b+': p['sign'] = 1
        elif c == 'r': p['kind'] = 'r'
        elif c == 'c': p['kind'] = 'c'
        elif c == 'k': p['kind'] = 'k'
        elif c == 't': p['transpose'] = True
        i += 1
    rest = s[i:]
    vec = ''
    m = re.match(r'^([^*vV]*)([*vV])(.*)$', rest)
    if m:
        rest, vtype, vec = m.group(1), m.group(2), m.group(3)
        p['vtype'] = 'external' if vtype == '*' else 'internal'
    dimre = re.compile(r'^(\d+)(?::(-?\d+)(?::(-?\d+))?)?([fFbBhH]|[eEoO]\d+)?$')
    def tensor(t):
        dims = []
        for d in t.split('x') if t else []:
            mm = dimre.match(d)
            assert mm, (s, d)
            dims.append(dict(n=int(mm.group(1)), strides=mm.group(2) is not None,
                             k=(mm.group(4) or '').lower()))
        return dims
    p['sz'] = tensor(rest)
    p['vecsz'] = tensor(vec)
    return p

def maxprime(n):
    best, d = 1, 2
    while d * d <= n:
        while n % d == 0:
            best, n = max(best, d), n // d
        d += 1
    return max(best, n) if n > 1 else best

def main():
    probs = []
    for line in open(sys.argv[1]):
        line = line.strip()
        if not line: continue
        parts = line.split()
        probs.append((parts[0], parts[-1]) if len(parts) > 1 else ('verify', parts[0]))
    seen = set(); uniq = []
    for kind, pr in probs:
        if (kind, pr) not in seen:
            seen.add((kind, pr)); uniq.append((kind, pr))
    c = collections.Counter()
    for kind, pr in uniq:
        if kind != 'verify':
            c['must-be-undoable (can-do #f)'] += 1; continue
        p = parse(pr)
        c['total doable problems'] += 1
        c['kind=' + {'c': 'complex dft', 'r': 'r2c/c2r (rdft2)', 'k': 'r2r'}[p['kind']]] += 1
        rank = len(p['sz']); vr = len(p['vecsz'])
        c['rank=%d' % rank] += 1
        c['vector rank=%d' % vr] += 1
        if p['split']: c['split re/im arrays'] += 1
        if p['inplace']: c['in-place'] += 1
        if p['destroy']: c['destroy-input allowed'] += 1
        if any(d['strides'] for d in p['sz'] + p['vecsz']): c['explicit strides'] += 1
        if p['kind'] == 'k':
            for d in p['sz']: c['r2r kind %s' % (d['k'] or 'f')] += 1
        mp = max([maxprime(d['n']) for d in p['sz']] or [1])
        c['max prime factor %s' % ('<=13' if mp <= 13 else '>13')] += 1
        tot = 1
        for d in p['sz']: tot *= d['n']
        if tot <= 1: c['transform size <= 1 (copy/rank-0-like)'] += 1
    for k, v in sorted(c.items()):
        print('%-45s %d' % (k, v))

if __name__ == '__main__':
    main()
